body.tpl-standard { font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; font-size: 11px; color: #1e293b; margin: 0; padding: 15px; background-color: #ffffff; }
.tpl-standard .header-table { width: 100%; border-bottom: 2px solid {{ $accentColor ?: '#1e3a8a' }}; padding-bottom: 8px; margin-bottom: 15px; }
.tpl-standard .company-name { font-size: 16px; font-weight: bold; color: {{ $accentColor ?: '#1e3a8a' }}; text-transform: uppercase; }
.tpl-standard .company-address { font-size: 9px; color: #64748b; }
.tpl-standard .payslip-title { font-size: 16px; font-weight: bold; color: {{ $accentColor ?: '#1e3a8a' }}; text-align: right; text-transform: uppercase; }
.tpl-standard .employee-info-table { width: 100%; background-color: #f8fafc; border: 1px solid #e2e8f0; border-collapse: collapse; margin-bottom: 15px; }
.tpl-standard .employee-info-table td { padding: 6px 10px; font-size: 10px; }
.tpl-standard .meta-label { color: #64748b; font-weight: 500; }
.tpl-standard .meta-val { font-weight: bold; color: #0f172a; }
.tpl-standard .components-table { width: 100%; border-collapse: collapse; margin-bottom: 15px; }
.tpl-standard .components-table th { background-color: #f1f5f9; color: #1e293b; padding: 7px; font-size: 10px; text-transform: uppercase; border: 1px solid #cbd5e1; }
.tpl-standard .components-table td { border: 1px solid #e2e8f0; padding: 6px 8px; font-size: 10px; }
.tpl-standard .net-pay-box { background-color: #f8fafc; border: 1px solid #cbd5e1; color: #0f172a; padding: 10px 14px; margin-bottom: 15px; border-left: 4px solid {{ $accentColor ?: '#1e3a8a' }}; }
.tpl-standard .net-amount { font-size: 15px; font-weight: bold; color: {{ $accentColor ?: '#1e3a8a' }}; }
.tpl-standard .net-words { font-size: 9.5px; font-style: italic; text-align: right; color: #475569; }
.tpl-standard .footer-note { text-align: center; font-size: 8.5px; color: #94a3b8; margin-top: 15px; border-top: 1px solid #f1f5f9; padding-top: 6px; }
